import os
import json
import pandas as pd
import pytest
from pathlib import Path
import sys

# Add code to path if not already there
sys.path.insert(0, str(Path(__file__).parent.parent.parent))

from code.data.preprocess import (
    generate_audit_sample,
    main,
    REPORTS_DIR
)
from code.utils.config import set_global_seed

@pytest.fixture
def sample_df():
    """Create a mock dataframe for testing."""
    set_global_seed(42)
    data = {
        "id": [f"PR-{i}" for i in range(1000)],
        "commit_message": [
            "Fix bug" if i % 2 == 0 else "Generated by Copilot fix"
            for i in range(1000)
        ],
        "classification": ["human" if i % 2 == 0 else "llm" for i in range(1000)],
        "diff": ["diff content"] * 1000,
        "project_name": ["test_proj"] * 1000
    }
    return pd.DataFrame(data)

def test_generate_audit_sample_size(sample_df):
    """Test that the generated sample has the correct size."""
    sample_size = 50
    result = generate_audit_sample(sample_df, sample_size=sample_size, seed=42)
    assert len(result) == sample_size

def test_generate_audit_sample_randomness(sample_df):
    """Test that the sample is actually random (different seeds give different results)."""
    sample1 = generate_audit_sample(sample_df, sample_size=10, seed=42)
    sample2 = generate_audit_sample(sample_df, sample_size=10, seed=123)
    # They should not be identical
    assert not sample1.equals(sample2)

def test_generate_audit_sample_columns(sample_df):
    """Test that the sample contains expected columns."""
    result = generate_audit_sample(sample_df, sample_size=10, seed=42)
    expected_cols = ["id", "commit_message", "classification", "diff", "project_name"]
    for col in expected_cols:
        assert col in result.columns

def test_main_generates_audit_csv(monkeypatch, tmp_path, sample_df):
    """Test that the main function generates the audit_sample.csv file."""
    # Mock the functions that load data and keywords
    import code.data.preprocess as preprocess_module
    
    original_load_keywords = preprocess_module.load_keywords
    original_load_dataset = preprocess_module.load_dataset_from_fetch
    
    # Mock keywords
    preprocess_module.load_keywords = lambda: ["copilot", "llm"]
    
    # Mock dataset fetch
    preprocess_module.load_dataset_from_fetch = lambda: sample_df
    
    # Mock the run_validation_pipeline to just return the df with classification
    def mock_run_validation(df, keywords, threshold=2):
        df["classification"] = df.apply(
            lambda row: "llm" if "llm" in row["commit_message"] else "human",
            axis=1
        )
        return df
    
    preprocess_module.run_validation_pipeline = mock_run_validation
    
    # Change output directory to tmp_path
    original_reports_dir = preprocess_module.REPORTS_DIR
    preprocess_module.REPORTS_DIR = tmp_path
    
    try:
        main()
        
        output_file = tmp_path / "audit_sample.csv"
        assert output_file.exists(), f"Output file {output_file} was not created"
        
        df_out = pd.read_csv(output_file)
        assert len(df_out) > 0, "Output file is empty"
        assert "id" in df_out.columns, "Missing 'id' column"
        assert "commit_message" in df_out.columns, "Missing 'commit_message' column"
        assert "classification" in df_out.columns, "Missing 'classification' column"
    finally:
        # Restore mocks
        preprocess_module.load_keywords = original_load_keywords
        preprocess_module.load_dataset_from_fetch = original_load_dataset
        preprocess_module.run_validation_pipeline = preprocess_module.run_validation_pipeline.__wrapped__ if hasattr(preprocess_module.run_validation_pipeline, '__wrapped__') else lambda df, keywords, threshold=2: df
        preprocess_module.REPORTS_DIR = original_reports_dir